/**
 * @fileoverview Test the overriding of an existing method
 * @author Sencha
 */
'use strict';

// ------------------------------------------------------------------------------
// Requirements
// ------------------------------------------------------------------------------

const rule = require('../../../lib/rules/no-existing-method-override'),
    RuleTester = require('eslint').RuleTester;

// ------------------------------------------------------------------------------
// Tests
// ------------------------------------------------------------------------------

const ruleTester = new RuleTester();
ruleTester.run('no-existing-method-override', rule, {

    valid: [
        {
            settings: {
                extjs: {
                    toolkit: 'modern',
                    version: '6.0'
                }
            },
            code: `
                Ext.extend(Ext, {
                    convertKeyedItems: true // this did NOT exist in 6.0 so was valid then
                });
            `
        },
        {
            settings: {
                extjs: {
                    toolkit: 'modern',
                    version: '6.0'
                }
            },
            code: `
                Ext.define('overrides.AbstractStore', {
                    override: 'Ext.data.AbstractStore',
                    createActiveRange: function () {}
                });
                Ext.define('MyStore', {
                    extend: 'Ext.data.Store',
                    createActiveRange: Ext.emptyFn
                });
            `
        },
        {
            code: `
                /**
                 * The following snippets are examples of VALID code
                 * with NESTED configs that should not be validated
                 * against a class in a higher up hierarchy
                 * 
                 * TODO - figure out how to actually validate the nested configs
                 */
                Ext.define('SimpleTasks.model.List', {
                    extend: 'Ext.data.Model',
                    proxy: {
                        type: 'ajax',
                        api: {
                            create: 'php/list/create.php',      // 'create' is ok since it is on the 'api' config
                            read: 'php/list/read.php',
                            update: 'php/list/update.php',
                            destroy: 'php/list/delete.php'      // 'destroy' is ok since it is on the 'api' config
                        },
                        reader: {
                            type: 'json',
                            messageProperty: 'message'
                        }
                    }
                });
            `
        }
    ],

    invalid: [
        {
            settings: {
                extjs: {
                    toolkit: 'modern',
                    fromVersion: '6.0',
                    toVersion: '7.9.0'
                }
            },
            code: `
                Ext.define('MyCustomComponent', {
                    extend: 'Ext.Component',
                    addCls: false,
                    setAlwaysOnTop: function () {},
                    getAlwaysOnTop: 2
                });
                Ext.create({
                    xclass: 'Ext.Component',
                    addCls: false,
                    setAlwaysOnTop: function () {},
                    getAlwaysOnTop: 2
                });
                
                // new methods in 7.4
                Ext.define('MyCustomClass', {
                    extend: 'Ext.data.Group',
                    collaspe: Ext.emptyFn, // TODO - is this a new method in 7.4?  It does not report an error
                    expand: Ext.emptyFn,
                    getGroupRecord: Ext.emptyFn,
                    toggleCollapsed: true
                })
            `,
            errors: [
                // errors in Ext.define()
                { message: /Override of existing method 'addCls' found for 'Ext.Component'.*/ },
                { message: /Override of existing method 'setAlwaysOnTop', for the 'alwaysOnTop' config, found for 'Ext.Component'.*/ },
                { message: /Override of existing method 'getAlwaysOnTop', for the 'alwaysOnTop' config, found for 'Ext.Component'.*/ },
                // errors in Ext.create()
                { message: /Override of existing method 'addCls' found for 'Ext.Component'.*/ },
                { message: /Override of existing method 'setAlwaysOnTop', for the 'alwaysOnTop' config, found for 'Ext.Component'.*/ },
                { message: /Override of existing method 'getAlwaysOnTop', for the 'alwaysOnTop' config, found for 'Ext.Component'.*/ },
                // errors for new methods in 7.4
                { message: /Override of existing method 'expand' found for 'Ext.data.Group'.*/ },
                { message: /Override of existing method 'getGroupRecord' found for 'Ext.data.Group'.*/ },
                { message: /Override of existing method 'toggleCollapsed' found for 'Ext.data.Group'.*/ }
            ]
        },
        {
            settings: {
                extjs: {
                    toolkit: 'modern',
                    version: '6.0',
                    toVersion: '7.9.0'
                }
            },
            code: `
                Ext.define('overrides.AbstractStore', {
                    override: 'Ext.data.AbstractStore',
                    createActiveRange: function () {}
                });
                Ext.define('MyStore', {
                    extend: 'Ext.data.Store',
                    createActiveRange: Ext.emptyFn
                });
            `,
            errors: [
                { message: /Override of existing method 'createActiveRange' found for 'Ext.data.AbstractStore'/ },
                { message: /Override of existing method 'createActiveRange' found for 'Ext.data.Store'/ }
            ]
        },
        {
            settings: {
                extjs: {
                    toolkit: 'modern',
                    version: '6.0'
                }
            },
            code: `
                Ext.define('SimpleTasks.model.List', {
                    extend: 'Ext.data.Model',
                    create: 'php/list/create.php',
                    destroy: 'php/list/delete.php'
                });
            `,
            errors: [
                { message: /Override of existing method 'create' found for 'Ext.data.Model'/ },
                { message: /Override of existing method 'destroy' found for 'Ext.data.Model'/ }
            ]
        }
    ]
});
